#Requires -Version 5.1
# Only in-memory adapters and generated byte buffers. Never runs a system command.
$ErrorActionPreference='Stop'
. "$PSScriptRoot/FullTweaks.Core.ps1";. "$PSScriptRoot/FullTweaks.Native.ps1"
Initialize-FullTweaks (Join-Path $PSScriptRoot ('.test-runs/full-adapters-'+[guid]::NewGuid().ToString('N'))) $true 26300
$pass=0
function Check([bool]$Ok,[string]$Name) {if (-not $Ok) {throw ('NATIVE ADAPTER FAILED: '+$Name)};$script:pass++;Write-Output ('PASS: '+$Name)}
function Reject([scriptblock]$Action) {try {& $Action | Out-Null;return $false} catch {return $true}}
$script:FullSimulation=$false
$adobe=Get-FullFeature WPFTweaksBlockAdobeNet
$original=[Text.Encoding]::UTF8.GetBytes("# máy thử nghiệm`r`n127.0.0.1 local.example`r`n")
$before=[pscustomobject]@{Bytes=[Convert]::ToBase64String($original)};$after=Get-FullNativeTarget $adobe @{} $before;$expanded=[Convert]::FromBase64String($after.Bytes)
Check ([Linq.Enumerable]::SequenceEqual([byte[]]$original,[byte[]]$expanded[0..($original.Length-1)])) 'Hosts preparation preserves every original byte including non-ASCII text'
Check ([Text.Encoding]::ASCII.GetString($expanded).Contains('# WinTuneVI Adobe BEGIN')) 'Hosts data is bounded by a WinTune-owned marker'
Check (Reject {Get-FullNativeTarget $adobe @{} $after}) 'A second hosts block is rejected before writing'
$script:Calls=@();$script:DnsState=[pscustomobject]@{Index=12;Guid='11111111-1111-1111-1111-111111111111';Manual=$false;Servers=@()}
function Get-Acl {param([string]$LiteralPath) return (New-Object Security.AccessControl.FileSecurity)}
$aclState=Get-FullNativeTarget (Get-FullFeature WPFTweaksDisableStoreSearch) @{} ([pscustomobject]@{Exists=$true})
$security=New-Object Security.AccessControl.FileSecurity;$security.SetSecurityDescriptorSddlForm($aclState.Sddl)
$denied=@($security.Access | Where-Object AccessControlType -eq Deny)[0].FileSystemRights
Check (([int]$denied -band [int][Security.AccessControl.FileSystemRights]::ReadPermissions) -eq 0 -and ([int]$denied -band [int][Security.AccessControl.FileSystemRights]::ChangePermissions) -eq 0) 'Store block preserves ACL read/change rights needed to verify and undo'
function Get-FullDnsState($Parameters) {return $script:DnsState}
function Set-DnsClientServerAddress {param($InterfaceIndex,$ServerAddresses,[switch]$ResetServerAddresses,$ErrorAction) $script:Calls+=,[pscustomobject]@{Index=$InterfaceIndex;Servers=@($ServerAddresses);Reset=[bool]$ResetServerAddresses};$script:DnsState=[pscustomobject]@{Index=12;Guid='11111111-1111-1111-1111-111111111111';Manual=(-not $ResetServerAddresses);Servers=$(if ($ResetServerAddresses) {@()} else {@($ServerAddresses)})}}
$dns=Get-FullFeature WPFchangedns;$parameters=[pscustomobject]@{InterfaceIndex=12;Provider='cloudflare'}
Write-FullNative $dns $parameters @{} $false
Check ($Calls.Count -eq 1 -and $Calls[0].Index -eq 12 -and ($Calls[0].Servers -join ',') -ceq '1.1.1.1,1.0.0.1') 'DNS changes exactly one selected adapter to a fixed provider pair'
$null=Assert-FullNativeResult $dns $parameters $DnsState $DnsState @{}
Check (Reject {Assert-FullNativeResult $dns $parameters $DnsState ([pscustomobject]@{Guid=$DnsState.Guid;Manual=$true;Servers=@('8.8.8.8')}) @{}}) 'DNS success requires the requested provider, not merely a nonempty server list'
$restore=[pscustomobject]@{Index=12;Guid=$DnsState.Guid;Manual=$false;Servers=@()};Write-FullNative $dns $parameters $restore $true
Check ($Calls[-1].Reset -and -not $DnsState.Manual) 'Undo restores DHCP mode instead of hardcoding old DHCP addresses'
$restore=[pscustomobject]@{Index=12;Guid=$DnsState.Guid;Manual=$true;Servers=@('9.9.9.9','149.112.112.112')};Write-FullNative $dns $parameters $restore $true
Check (($Calls[-1].Servers -join ',') -ceq '9.9.9.9,149.112.112.112') 'Undo preserves manual DNS addresses and order'
$restore.Guid='22222222-2222-2222-2222-222222222222';$count=$Calls.Count
Check (Reject {Write-FullNative $dns $parameters $restore $true}) 'A replaced adapter identity blocks DNS restore'
Check ($Calls.Count -eq $count) 'Rejected restore does not call the network writer'
$parameters.Provider='injected;command';Check (Reject {Write-FullNative $dns $parameters @{} $false}) 'Unknown provider cannot become an executable command'
$a=Get-FullFeature WPFTweaksDisableBitLocker
Check (Reject {Assert-FullNativeResult $a @{} @{} ([pscustomobject]@{Status='FullyEncrypted'}) @{}}) 'BitLocker never claims success while the drive remains fully encrypted'
$null=Assert-FullNativeResult $a @{} @{} ([pscustomobject]@{Status='DecryptionInProgress'}) @{}
Check $true 'BitLocker reports starting decryption without pretending to wait for completion'
$a=Get-FullFeature WPFTweaksWindowsAI
Check (Reject {Assert-FullNativeResult $a @{} @{} ([pscustomobject]@{Apps=@('protected');Recall='Disabled'}) @{}}) 'A protected AI package is not silently counted as removed'
$a=Get-FullFeature WPFTweaksDeleteTempFiles
Check (Reject {Assert-FullNativeResult $a @{} @{} ([pscustomobject]@{Files=@();SkippedDirectories=1}) @{}}) 'Unreadable TEMP folders prevent a false all-cleaned result'
Check ((Get-FullServiceTarget Manual ([pscustomobject]@{Exists=$true;Start=2;Delayed=1})).Delayed -eq 1) 'Service planning preserves the delayed-start setting'
Check (Reject {Get-FullServiceTarget Disabled ([pscustomobject]@{Exists=$false})}) 'Missing services never become new registry service entries'
Check (Reject {Get-FullBase HKCR}) 'Unlisted registry hives are not accepted'

# WindowsAI must distinguish an absent Recall feature from unreadable servicing
# state, and must perform this check before any irreversible app removal.
$script:RecallReadFail=$false;$script:RecallState='Enabled';$script:RecallMutations=0;$script:RecallApps=@()
function Get-WindowsOptionalFeature {
    param([switch]$Online,[string]$FeatureName,[string]$ErrorAction)
    if ($script:RecallReadFail) {Write-Error 'Injected servicing query failure' -ErrorAction $ErrorAction;return}
    if ($script:RecallState -ne 'Absent') {[pscustomobject]@{FeatureName='Recall';State=$script:RecallState}}
}
function Get-FullApps([string[]]$Names) {return @($script:RecallApps)}
function Read-FullRegistry($Change) {return [pscustomobject]@{Exists=$false;KeyExisted=$false;Type=$Change.Type;Value=$null}}
function Remove-AppxPackage {param([string]$Package,[string]$ErrorAction) $script:RecallMutations++;$script:RecallApps=@()}
function Disable-WindowsOptionalFeature {param([switch]$Online,[string]$FeatureName,[switch]$NoRestart,[string]$ErrorAction) $script:RecallMutations++;$script:RecallState='DisablePending'}
$ai=Get-FullFeature WPFTweaksWindowsAI
$script:RecallReadFail=$true
Check (Reject {Read-FullNative $ai @{}}) 'Unreadable Recall inventory is not treated as an absent feature'
Check (Reject {Write-FullNative $ai @{} @{} $false}) 'WindowsAI stops when Recall state cannot be read'
Check ($script:RecallMutations -eq 0) 'Recall read failure performs zero app or optional-feature mutations'
$script:RecallReadFail=$false;$script:RecallState='EnablePending'
Check (Reject {New-FullPlan @($ai.Id) @{}}) 'WindowsAI preview refuses a pending Recall restart before creating a plan'
Check (Reject {Write-FullNative $ai @{} @{} $false}) 'WindowsAI waits for a pending Recall restart before removing apps'
Check ($script:RecallMutations -eq 0) 'Pending Recall restart performs zero irreversible mutations'
$script:RecallState='Unrecognized'
Check (Reject {Read-FullNative $ai @{}}) 'Unknown Recall servicing states fail closed'
$script:RecallState='Absent'
Check ((Read-FullNative $ai @{}).Recall -eq 'Absent') 'Successful inventory can explicitly establish that Recall is absent'
$script:RecallState='Disabled';$script:RecallApps=@([pscustomobject]@{Name='Microsoft.Copilot';FullName='fixture-removable';NonRemovable=$false},[pscustomobject]@{Name='MicrosoftWindows.Client.CoreAI';FullName='fixture-protected';NonRemovable=$true})
Check (Reject {New-FullPlan @($ai.Id) @{}}) 'WindowsAI preview rejects a protected package before any registry or app changes'
Check (Reject {Write-FullNative $ai @{} @{} $false}) 'A protected AI package prevents the full app removal pass'
Check ($script:RecallMutations -eq 0 -and $script:RecallApps.Count -eq 2) 'Protected second package is detected before removing the first package'
$script:RecallState='Enabled';$script:RecallApps=@([pscustomobject]@{Name='Microsoft.Copilot';FullName='fixture-only';NonRemovable=$false})
Write-FullNative $ai @{} @{} $false
$after=Read-FullNative $ai @{}
$null=Assert-FullNativeResult $ai @{} @{} $after @{}
Check ($script:RecallMutations -eq 2 -and $after.Recall -eq 'DisablePending' -and $after.Apps.Count -eq 0) 'Known enabled Recall is disabled without reboot and its pending completion is verified'
Write-Output "FULL NATIVE ADAPTER TESTS PASSED: $pass; no native Windows command executed."
